static int cmp_pair(const void *a, const void *b) {
    const Pair *p = (const Pair *)a;
    const Pair *q = (const Pair *)b;
    if (p->key < q->key) return -1;
    if (p->key > q->key) return 1;
    return p->idx - q->idx;
}

static uint64_t hash_key(i64 key) {
    uint64_t z = (uint64_t)key + 0x9e3779b97f4a7c15ULL;
    z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
    z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
    return z ^ (z >> 31);
}

static void hashmap_init(HashMap *h, size_t cap) {
    h->cap = cap;
    h->keys = (i64 *)malloc(cap * sizeof(i64));
    h->ids = (int *)malloc(cap * sizeof(int));
    for (size_t i = 0; i < cap; ++i) h->ids[i] = -1;
}

static void hashmap_put(HashMap *h, i64 key, int id) {
    size_t pos = (size_t)hash_key(key) & (h->cap - 1);
    while (h->ids[pos] != -1) pos = (pos + 1) & (h->cap - 1);
    h->keys[pos] = key;
    h->ids[pos] = id;
}

static int hashmap_get(const HashMap *h, i64 key) {
    size_t pos = (size_t)hash_key(key) & (h->cap - 1);
    while (h->ids[pos] != -1) {
        if (h->keys[pos] == key) return h->ids[pos];
        pos = (pos + 1) & (h->cap - 1);
    }
    return -1;
}

